3	/**
4	 * Signs a user in and sets the session cookie.
5	 *
6	 * Owner D. Runs before any tenant is known, so it cannot go through
7	 * `withAction()` — there is no `Actor` to resolve yet. The rate limit is
8	 * charged against the anonymous bucket to blunt credential stuffing.
9	 *
10	 * Must call (do not reimplement): loginSchema, setSessionCookie,
11	 * consumeRateLimit
12	 */
13	
14	import { ANONYMOUS_ORG_ID } from "@/actions/_lib/permission-resources";
15	import { RateLimitedError } from "@/actions/_lib/action-errors";
16	import { toActionResult } from "@/lib/errors";
17	import { consumeRateLimit } from "@/lib/rate-limit";
18	import { setSessionCookie } from "@/lib/session";
19	import { loginSchema } from "@/schemas/auth";
